package com.example.user_service.service;
import com.example.user_service.dto.ProfileDtos; import com.example.user_service.entity.CandidateProfile; import com.example.user_service.repository.CandidateProfileRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service public class ProfileService {private final CandidateProfileRepository repo;public ProfileService(CandidateProfileRepository r){repo=r;} @Transactional public ProfileDtos.View get(UUID userId){return view(repo.findByUserId(userId).orElseGet(()->repo.save(new CandidateProfile(userId))));} @Transactional public ProfileDtos.View update(UUID userId,ProfileDtos.Update x){CandidateProfile p=repo.findByUserId(userId).orElseGet(()->new CandidateProfile(userId));p.update(x.fullName(),x.phone(),x.headline(),x.summary(),x.locationId());return view(repo.save(p));} private ProfileDtos.View view(CandidateProfile p){return new ProfileDtos.View(p.getId(),p.getUserId(),p.getFullName(),p.getPhone(),p.getHeadline(),p.getSummary(),p.getLocationId(),p.getCreatedAt(),p.getUpdatedAt(),p.getVersion());}}
